var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var W = 10;
var cores = [].slice.call(root.querySelectorAll('.trm5-proc-top-core'));
var rows = [].slice.call(root.querySelectorAll('.trm5-proc-top-row'));
var cv = [38, 67, 19, 91];
var procs = [
  {p:1284,u:'www',c:12.4,m:3.1,n:'node dist/server.js'},
  {p:902,u:'pgsql',c:8.7,m:11.4,n:'postgres: writer'},
  {p:441,u:'redis',c:4.2,m:2.8,n:'redis-server *:6379'},
  {p:77,u:'root',c:1.9,m:0.6,n:'nginx: worker'},
  {p:2210,u:'app',c:0.8,m:5.2,n:'python3 -m celery'}
];
function rep(ch, n){ return n > 0 ? new Array(n + 1).join(ch) : ''; }
function lv(p){ return p < 55 ? 1 : p < 82 ? 2 : 3; }
function paintCore(i){
  var el = cores[i]; if(!el) return;
  var p = cv[i], n = Math.round(p / 100 * W);
  var on = el.querySelector('.trm5-proc-top-on');
  var off = el.querySelector('.trm5-proc-top-off');
  on.textContent = rep('|', n);
  off.textContent = rep('|', W - n);
  on.className = 'trm5-proc-top-on trm5-proc-top-lv' + lv(p);
  el.querySelector('.trm5-proc-top-pct').textContent = Math.round(p);
}
function draw(){
  for(var i = 0; i < cores.length; i++) paintCore(i);
  var s = procs.slice().sort(function(a,b){ return b.c - a.c; });
  for(var j = 0; j < rows.length; j++){
    var r = rows[j], d = s[j];
    if(!d) continue;
    r.children[0].textContent = d.p;
    r.children[1].textContent = d.u;
    r.children[2].textContent = d.c.toFixed(1);
    r.children[3].textContent = d.m.toFixed(1);
    r.children[4].textContent = d.n;
    r.className = 'trm5-proc-top-row' + (j === 0 ? ' trm5-proc-top-hot' : '');
  }
}
function step(){
  for(var i = 0; i < cv.length; i++){
    cv[i] = Math.max(2, Math.min(99, cv[i] + (Math.random() - 0.5) * 26));
  }
  for(var k = 0; k < procs.length; k++){
    procs[k].c = Math.max(0.1, procs[k].c + (Math.random() - 0.47) * 3.4);
    if(procs[k].c > 40) procs[k].c = 40 - Math.random() * 9;
    procs[k].m = Math.max(0.2, Math.min(38, procs[k].m + (Math.random() - 0.5) * 0.6));
  }
  root.querySelector('.trm5-proc-top-tasks').textContent = 210 + Math.floor(Math.random() * 9);
  root.querySelector('.trm5-proc-top-run').textContent = 1 + Math.floor(Math.random() * 4);
  var a = (cv[0] + cv[1] + cv[2] + cv[3]) / 100;
  root.querySelector('.trm5-proc-top-ld').textContent = a.toFixed(2) + ' ' + (a * 0.83 + 0.1).toFixed(2) + ' ' + (a * 0.6 + 0.22).toFixed(2);
  draw();
}
