var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var pane = root.querySelector('.trm5-log-tail-body');
var cnt = root.querySelector('.trm5-log-tail-cnt');
var errn = root.querySelector('.trm5-log-tail-errn');
var rate = root.querySelector('.trm5-log-tail-rate');
var total = 1284, errs = 3, timer = null;
var pool = [
  ['inf','INF','edge: GET /v1/orders 200 14ms'],
  ['inf','INF','edge: GET /v1/users/8821 200 9ms'],
  ['inf','INF','auth: token refreshed uid=4471'],
  ['inf','INF','edge: POST /v1/pay 201 38ms'],
  ['inf','INF','worker: job 91f4 done 1.2s'],
  ['inf','INF','edge: GET /health 200 1ms'],
  ['dbg','DBG','pool: acquired conn 12/32'],
  ['dbg','DBG','cache: hit ratio 0.94'],
  ['dbg','DBG','gc: pause 3.1ms heap 214MB'],
  ['wrn','WRN','db: slow query 812ms on orders'],
  ['wrn','WRN','retry 2/5 backoff 400ms'],
  ['err','ERR','upstream 10.0.4.7 refused conn'],
  ['err','ERR','tls: handshake timeout peer']
];
function pick(){
  var r = Math.random();
  var f = r < 0.06 ? 'err' : r < 0.18 ? 'wrn' : r < 0.42 ? 'dbg' : 'inf';
  var c = [];
  for(var i = 0; i < pool.length; i++) if(pool[i][0] === f) c.push(pool[i]);
  return c[Math.floor(Math.random() * c.length)];
}
function p2(n){ return (n < 10 ? '0' : '') + n; }
function stamp(){ var d = new Date(); return p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds()); }
function group(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' '); }
function add(){
  var m = pick();
  var r = document.createElement('div');
  r.className = 'trm5-log-tail-row trm5-log-tail-new';
  var a = document.createElement('span'); a.className = 'trm5-log-tail-ts'; a.textContent = stamp();
  var b = document.createElement('span'); b.className = 'trm5-log-tail-lvl trm5-log-tail-' + m[0]; b.textContent = m[1];
  var c = document.createElement('span'); c.className = 'trm5-log-tail-msg'; c.textContent = m[2];
  r.appendChild(a); r.appendChild(b); r.appendChild(c);
  pane.appendChild(r);
  while(pane.children.length > 40) pane.removeChild(pane.firstChild);
  pane.scrollTop = pane.scrollHeight;
  total++; if(m[0] === 'err') errs++;
  cnt.textContent = group(total);
  errn.textContent = errs;
}
function loop(){
  add();
  rate.textContent = (6 + Math.floor(Math.random() * 22)) + '/s';
  timer = setTimeout(loop, 220 + Math.random() * 720);
}
pane.scrollTop = pane.scrollHeight;
if(!reduce) timer = setTimeout(loop, 400);

