var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = [].slice.call(root.querySelectorAll('.trm5-disk-tree-row'));
var sizes = [42.1, 31.4, 8.9, 38.6, 21.7, 9.4];
var names = ['/var', '/var/lib', '/var/log', '/home', '/usr', '/opt'];
var idx = 0;
function rep(ch, n){ return n > 0 ? new Array(n + 1).join(ch) : ''; }
function paint(){
  var max = 1, i;
  for(i = 0; i < sizes.length; i++) if(sizes[i] > max) max = sizes[i];
  for(i = 0; i < rows.length; i++){
    rows[i].querySelector('.trm5-disk-tree-sz').textContent = sizes[i].toFixed(1) + 'G';
    var n = Math.max(1, Math.round(sizes[i] / max * 6));
    rows[i].querySelector('.trm5-disk-tree-bon').textContent = rep('█', n);
    rows[i].querySelector('.trm5-disk-tree-boff').textContent = rep('·', 6 - n);
  }
  var tot = 34.2;
  for(i = 0; i < sizes.length; i++) tot += sizes[i];
  var pct = Math.max(1, Math.min(99, Math.round(tot / 232 * 100)));
  root.querySelector('.trm5-disk-tree-tot').textContent = Math.round(tot) + 'G/232G';
  root.querySelector('.trm5-disk-tree-pct').textContent = pct + '%';
  var f = Math.round(pct / 100 * 16);
  root.querySelector('.trm5-disk-tree-mon').textContent = rep('█', f);
  root.querySelector('.trm5-disk-tree-moff').textContent = rep('░', 16 - f);
}
function step(){
  for(var i = 0; i < rows.length; i++) rows[i].className = 'trm5-disk-tree-row';
  rows[idx].className = 'trm5-disk-tree-row trm5-disk-tree-scan';
  sizes[idx] = Math.max(0.4, sizes[idx] + (Math.random() - 0.45) * 0.7);
  root.querySelector('.trm5-disk-tree-cur').textContent = 'scan ' + names[idx] + ' …';
  paint();
  idx = (idx + 1) % rows.length;
}
paint();
if(!reduce) setInterval(step, 430);

