var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var L = [0x40, 0x04, 0x02, 0x01], R = [0x80, 0x20, 0x10, 0x08];
var grids = [root.querySelector('.trm5-net-braille-grx'), root.querySelector('.trm5-net-braille-gtx')];
var lines = [grids[0].querySelectorAll('.trm5-net-braille-line'), grids[1].querySelectorAll('.trm5-net-braille-line')];
var cw = 6.6;
var probe = document.createElement('span');
probe.textContent = '⣿⣿⣿⣿⣿⣿⣿⣿⣿⣿';
probe.style.cssText = 'position:absolute;left:-9999px;visibility:hidden;white-space:pre;font-size:11px';
grids[0].appendChild(probe);
var pw = probe.getBoundingClientRect().width;
if(pw > 0) cw = pw / 10;
grids[0].removeChild(probe);
var gw = grids[0].getBoundingClientRect().width || 232;
var CELLS = Math.max(14, Math.floor(gw / cw));
var N = CELLS * 2;
function clamp(x){ return x < 0.2 ? 0.2 : x > 8 ? 8 : x; }
function sub(v, r){ var k = Math.round(v) - (r === 0 ? 4 : 0); return k < 0 ? 0 : k > 4 ? 4 : k; }
var data = [[], []], peak = 4.2;
for(var s = 0; s < 2; s++){
  var v = s ? 2.2 : 5;
  for(var i = 0; i < N; i++){ v = clamp(v + (Math.random() - 0.5) * 2.2); data[s].push(v); }
}
function draw(s){
  for(var r = 0; r < 2; r++){
    var out = '';
    for(var c = 0; c < CELLS; c++){
      var a = sub(data[s][c * 2], r), b = sub(data[s][c * 2 + 1], r), code = 0x2800, k;
      for(k = 0; k < a; k++) code |= L[k];
      for(k = 0; k < b; k++) code |= R[k];
      out += String.fromCharCode(code);
    }
    lines[s][r].textContent = out;
  }
}
function step(){
  for(var s = 0; s < 2; s++){
    var last = data[s][N - 1];
    var burst = Math.random() < 0.07 ? (Math.random() - 0.4) * 5 : 0;
    data[s].push(clamp(last + (Math.random() - 0.5) * 2.6 + burst));
    data[s].shift();
    draw(s);
  }
  var rx = data[0][N - 1] / 8 * 9.6, tx = data[1][N - 1] / 8 * 3.2;
  if(rx > peak) peak = rx;
  root.querySelector('.trm5-net-braille-rxv').textContent = '▼ ' + rx.toFixed(2) + ' MB/s';
  root.querySelector('.trm5-net-braille-txv').textContent = '▲ ' + tx.toFixed(2) + ' MB/s';
  root.querySelector('.trm5-net-braille-a2').textContent = 'peak ' + peak.toFixed(1) + ' MB/s';
}
draw(0); draw(1); step();
if(!reduce) setInterval(step, 340);

