var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = [].slice.call(root.querySelectorAll('.trm5-cron-table-row'));
var per = [300, 3600, 900, 86400, 604800];
var next = [9, 26, 44, 73, 120];
var last = [291, 3574, 856, 82800, 518400];
var fire = [0, 0, 0, 0, 0];
function p2(n){ return (n < 10 ? '0' : '') + n; }
function dur(s){
  if(s >= 86400) return Math.floor(s / 86400) + 'd' + Math.floor(s % 86400 / 3600) + 'h';
  if(s >= 3600) return Math.floor(s / 3600) + 'h' + p2(Math.floor(s % 3600 / 60)) + 'm';
  if(s >= 60) return Math.floor(s / 60) + 'm' + p2(s % 60) + 's';
  return s + 's';
}
function paint(){
  var mn = 0, i;
  for(i = 1; i < next.length; i++) if(next[i] < next[mn]) mn = i;
  for(i = 0; i < rows.length; i++){
    rows[i].querySelector('.trm5-cron-table-c3').textContent = dur(last[i]);
    rows[i].querySelector('.trm5-cron-table-c4').textContent = fire[i] > 0 ? 'RUN' : dur(next[i]);
    var cls = 'trm5-cron-table-row';
    if(i === mn) cls += ' trm5-cron-table-soon';
    if(fire[i] > 0) cls += ' trm5-cron-table-fire';
    if(rows[i].className !== cls) rows[i].className = cls;
  }
}
function tick(){
  for(var i = 0; i < next.length; i++){
    next[i]--; last[i]++;
    if(fire[i] > 0) fire[i]--;
    if(next[i] <= 0){ next[i] = per[i]; last[i] = 0; fire[i] = 3; }
  }
  var d = new Date();
  root.querySelector('.trm5-cron-table-now').textContent = p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());
  paint();
}
paint();
if(!reduce) setInterval(tick, 1000);

