js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = [].slice.call(root.querySelectorAll('.trm5-container-ls-row'));
var cpu = [0.4, 2.1, 0.8, 1.2];
var spin = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏';
var si = 0, t = 0;
var flap = rows[3];
function phase(){ return t % 18; }
function paintFlap(){
  if(!flap) return;
  var m = phase();
  var st = flap.querySelector('.trm5-container-ls-c3');
  var c4 = flap.querySelector('.trm5-container-ls-c4');
  if(m < 5){
    flap.className = 'trm5-container-ls-row trm5-container-ls-warn';
    st.textContent = spin.charAt(si) + ' Restarting';
    c4.textContent = '—';
  } else if(m < 15){
    flap.className = 'trm5-container-ls-row trm5-container-ls-ok';
    st.textContent = 'Up ' + (m - 4) + 's';
    c4.textContent = cpu[3].toFixed(1);
  } else {
    flap.className = 'trm5-container-ls-row trm5-container-ls-bad';
    st.textContent = 'Exited (137)';
    c4.textContent = '—';
  }
  var run = 3 + (m >= 5 && m < 15 ? 1 : 0);
  root.querySelector('.trm5-container-ls-run').textContent = run + ' running';
}
function stats(){
  t++;
  for(var i = 0; i < 3; i++){
    cpu[i] = Math.max(0.1, cpu[i] + (Math.random() - 0.5) * 1.3);
    if(cpu[i] > 9) cpu[i] = 9 - Math.random();
    rows[i].querySelector('.trm5-container-ls-c4').textContent = cpu[i].toFixed(1);
  }
  cpu[3] = Math.max(0.2, Math.min(6, cpu[3] + (Math.random() - 0.42) * 1.6));
  paintFlap();
}
function spinTick(){ si = (si + 1) % 10; if(phase() < 5) paintFlap(); }
paintFlap();
if(!reduce){ setInterval(stats, 1000); setInterval(spinTick, 100); }

