.trm5-res-meters .trm5-res-meters-ld{color:var(--trm5-fg)}
@keyframes trm5-res-meters-alarm{0%,55%{opacity:1}56%,100%{opacity:.35}}
@media (prefers-reduced-motion: reduce){.trm5-res-meters .trm5-res-meters-r .trm5-res-meters-val{animation:none}}

js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var ms = [].slice.call(root.querySelectorAll('.trm5-res-meters-m'));
var v = [62, 74, 18, 41, 55];
var peak = 94;
var part = ['▁', '▂', '▃', '▄', '▅', '▆', '▇'];
function paint(){
  for(var i = 0; i < ms.length; i++){
    var cells = ms[i].querySelectorAll('.trm5-res-meters-cell');
    var n = cells.length;
    var u = v[i] / 100 * n, full = Math.floor(u), frac = u - full;
    for(var c = 0; c < n; c++){
      if(c < full){
        cells[c].textContent = '█';
        cells[c].className = 'trm5-res-meters-cell trm5-res-meters-on';
      } else if(c === full && frac > 0.12){
        cells[c].textContent = part[Math.min(6, Math.floor(frac * 7))];
        cells[c].className = 'trm5-res-meters-cell trm5-res-meters-on';
      } else {
        cells[c].textContent = '█';
        cells[c].className = 'trm5-res-meters-cell';
      }
    }
    ms[i].className = 'trm5-res-meters-m ' + (v[i] < 60 ? 'trm5-res-meters-g' : v[i] < 85 ? 'trm5-res-meters-a' : 'trm5-res-meters-r');
    ms[i].querySelector('.trm5-res-meters-val').textContent = Math.round(v[i]);
  }
  root.querySelector('.trm5-res-meters-pk').textContent = Math.round(peak) + '%';
  root.querySelector('.trm5-res-meters-ld').textContent = (v[0] / 100 * 3.4 + 0.1).toFixed(2);
}
function step(){
  var amp = [17, 5, 2, 22, 19];
  for(var i = 0; i < v.length; i++){
    v[i] = Math.max(2, Math.min(99, v[i] + (Math.random() - 0.5) * amp[i]));
  }
  peak = Math.max(v[0], peak - 0.4);
  paint();
}
paint();
if(!reduce) setInterval(step, 900);
